9.1 Idempotency Key + Guarded ERPNext Wr:
import hashlib, json

def idempotency_key(workflow_id: str, step: str, attempt_input: dict) -> str:
    payload = json.dumps({"w": workflow_id, "s": step, "i": attempt_input}, sort_keys=True)
    return hashlib.sha256(payload.encode()).hexdigest()

def submit_once(erp, doctype: str, doc: dict, key: str, db) -> str:
    # If this key already committed a document, return it — never post twice.
    existing = db.get_committed(key)
    if existing:
        return existing                      # crash-safe / retry-safe replay
    name = erp.insert_and_submit(doctype, doc)   # real ERPNext write + submit
    db.record_committed(key, name)               # durable before returning
    return name

9.3 Conformal Routing (Phase 3):
def route(region) -> Route:
    # Prediction region derived from calibrated nonconformity scores.
    # Singleton, confident region -> commit; ambiguous region -> escalate.
    if region.is_singleton() and region.covers("commit"):
        return Route.COMMIT
    if region.is_singleton() and region.covers("escalate"):
        return Route.ESCALATE
    return Route.ESCALATE   # ambiguity defaults to human, never silent commit

9.4 Verifier Independence Guard (Rule 3):
def build_verifier_payload(ctx) -> dict:
    payload = {
        "step_context": ctx.step_context,
        "proposed_action": ctx.proposed_action,
        # NOTE: executor rationale is deliberately excluded to prevent anchoring.
    }
    assert "rationale" not in payload, "Rule 3: verifier must not see executor rationale"
    return payload
